#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_all_non_zero(void) {
    // Setup: Build a linked list with at least two nodes.
    // The target node is NOT the head, and we update with all non-zero values.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Initial state check: all CT, WT, TAT should be zero.
    node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        TEST_ASSERT_EQUAL_INT(0, ptr->WT);
        TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        ptr = ptr->next;
    }

    // Test: Update the second node (ID=2) with all non-zero values.
    // This triggers the path where:
    // - ptr != NULL && ptr->ID != id (head condition false, enter while loop)
    // - Loop exits when ptr->ID == id (found node 2)
    // - ct != 0, wt != 0, tat != 0 all true, so all three fields are updated.
    int target_id = 2;
    int new_ct = 10;
    int new_wt = 4;
    int new_tat = 9;
    update(&root, target_id, new_ct, new_wt, new_tat);

    // Verify the updated node.
    ptr = root;
    while (ptr != NULL && ptr->ID != target_id) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(target_id, ptr->ID);
    TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
    TEST_ASSERT_EQUAL_INT(new_wt, ptr->WT);
    TEST_ASSERT_EQUAL_INT(new_tat, ptr->TAT);

    // Verify other nodes are unchanged.
    ptr = root;
    while (ptr != NULL) {
        if (ptr->ID != target_id) {
            TEST_ASSERT_EQUAL_INT(0, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        }
        ptr = ptr->next;
    }

    // Cleanup.
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_all_non_zero);
    return UNITY_END();
}

